	private static BatchCursor tripAfterFirstBatch(BatchCursor delegate, RowState row,
			LmdbNativeProbeDeadline deadline, AtomicInteger batches, AtomicBoolean interrupted) {
		return new BatchCursor() {
			private boolean emitted;

			@Override
			public int fill(NativeBatch batch) throws IOException {
				if (emitted) {
					assertThat(row.boundMask()).as("the ordered merge installed a row before interruption").isNotZero();
					interrupted.set(true);
					deadline.trip();
					LmdbNativeProbeDeadline.poll(0);
				}
				int count = delegate.fill(batch);
				if (count > 0) {
					emitted = true;
					batches.incrementAndGet();
				}
				return count;
			}

			@Override
			public void close() {
				delegate.close();
			}
		};
	}

	private static LmdbNativeAdaptiveArbitration.Priced<List<BindingSet>> find(
			List<LmdbNativeAdaptiveArbitration.Priced<List<BindingSet>>> candidates, String family) {
		return candidates.stream()
				.filter(candidate -> family.equals(candidate.candidate().estimate().variantKey().strategyFamily()))
				.findFirst()
				.orElse(null);
	}

	private static LmdbNativeAdaptiveArbitration.DispatchPlan.Probe<List<BindingSet>> scriptedProbe(
			LmdbNativeAdaptiveArbitration.Priced<List<BindingSet>> trial,
			LmdbNativeAdaptiveArbitration.Priced<List<BindingSet>> fallback, LmdbNativeAdaptiveCostModel model,
			LmdbNativeAdaptiveArbitration.ProbeContext context) {
		assertTrue(context.queryBudget().tryConsume(context.config().maxPerQuery()));
		LmdbNativeRegimeTracker.Snapshot regime = model.store().regimeTracker().snapshot();
		LmdbNativeProbeScheduler.Flight flight = model.store()
				.probeScheduler()
				.tryBeginProbe(trial.candidate().estimate().variantKey(), regime.regime(), regime.epoch());
		assertNotNull(flight);
		LmdbNativeSafetyLedger.Reservation reservation = model.store().safetyLedger().reserveMandatory(1_000_000_000L);
		return new LmdbNativeAdaptiveArbitration.DispatchPlan.Probe<>(trial.candidate(), trial.prediction(),
				fallback.candidate(), fallback.prediction(), 30_000_000_000L, reservation,
				regime.regime(), regime.epoch(), "controlled ordered probe", flight);
	}

	private static List<BindingSet> rows(SailRepository repository, String query) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			return QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
		}
	}

	private static void set(Map<String, String> saved, String property, String value) {
		saved.put(property, System.getProperty(property));
		System.setProperty(property, value);
	}

	private static void restore(Map<String, String> saved) {
		saved.forEach((key, value) -> {
			if (value == null) {
				System.clearProperty(key);
			} else {
				System.setProperty(key, value);
			}
		});
	}
